import{_ as n,C as s,o as d,c as e,j as i,E as r,a as l,a2 as o}from"./chunks/framework.C21TwvGF.js";const z=JSON.parse(`{"title":"1-hafta (Mentor)","description":"","frontmatter":{"title":"1-hafta (Mentor)","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_hafta","hafta":{"sinf":{"name":"9-sinf (IoT)","link":"/mentor/9-sinf-iot/"},"n":1,"bob":"I-bob · IoT asoslari va virtual laboratoriya","lessons":[{"g":1,"title":"IoT tushunchasi va qo‘llanish sohalari","lead":"IoT tushunchasi va qo‘llanish sohalari","link":"/mentor/9-sinf-iot/hafta-01/dars-1","slide":"/slaydlar/9-sinf-iot/hafta-01/dars-1.html","test":"/slaydlar/9-sinf-iot/hafta-01/dars-1-test.html"},{"g":2,"title":"IoT arxitekturasi: Sensorlar, aktuatorlar va apparat ta'minoti","lead":"IoT arxitekturasi: Sensorlar, aktuatorlar va apparat ta'minoti","link":"/mentor/9-sinf-iot/hafta-01/dars-2","slide":"/slaydlar/9-sinf-iot/hafta-01/dars-2.html","test":"/slaydlar/9-sinf-iot/hafta-01/dars-2-test.html"},{"g":3,"title":"IoT arxitekturasi: Tarmoq, bulut va foydalanuvchi interfeysi","lead":"IoT arxitekturasi: Tarmoq, bulut va foydalanuvchi interfeysi","link":"/mentor/9-sinf-iot/hafta-01/dars-3","slide":"/slaydlar/9-sinf-iot/hafta-01/dars-3.html","test":"/slaydlar/9-sinf-iot/hafta-01/dars-3-test.html"}],"test":"/slaydlar/9-sinf-iot/hafta-01/hafta-test.html"}},"headers":[],"relativePath":"mentor/9-sinf-iot/hafta-01/index.md","filePath":"mentor/9-sinf-iot/hafta-01/index.md"}`),h={name:"mentor/9-sinf-iot/hafta-01/index.md"},u={class:"blk"},m={id:"uyga-vazifa-va-mentor-tavsiyalari",tabindex:"-1"},b={class:"blk"},g={id:"baholash-mezoni",tabindex:"-1"};function k(v,a,y,q,c,f){const t=s("Icon");return d(),e("div",null,[i("div",u,[i("h2",m,[r(t,{name:"house"}),a[0]||(a[0]=l(" Uyga vazifa va mentor tavsiyalari ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#uyga-vazifa-va-mentor-tavsiyalari","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa va mentor tavsiyalari"'},"​",-1))]),a[2]||(a[2]=o('<p>Mazkur haftada o&#39;tilgan darslar bo&#39;yicha mustaqil bajarish uchun topshiriqlar. Har bir vazifa 20–30 daqiqaga mo&#39;ljallangan.</p><hr><h2 id="_1-dars-iot-tushunchasi-va-qo-llanish-sohalari" tabindex="-1">1-dars: IoT tushunchasi va qo‘llanish sohalari <a class="header-anchor" href="#_1-dars-iot-tushunchasi-va-qo-llanish-sohalari" aria-label="Permalink to &quot;1-dars: IoT tushunchasi va qo‘llanish sohalari&quot;">​</a></h2><ol><li>O&#39;zingiz yashayotgan xonadonda yoki maktabda IoT yordamida avtomatlashtirish mumkin bo&#39;lgan 2 ta muammoni aniqlang (masalan, chiroqni o&#39;chirishni unutish, gulni qachon sug&#39;orishni bilmaslik).</li><li>Ushbu muammolarni an&#39;anaviy yechim va IoT yechimi nuqtai nazaridan solishtirib bering.</li><li>Har bir tizim qaysi sohaga (Smart Home, Smart Agriculture, IIoT yoki Smart City) tegishli ekanini yozing.</li><li>Tizimda inson omilini kamaytirish (M2M — Machine to Machine tamoyili) qanday afzallik keltirishini 3 ta jumla bilan ifodalang.</li></ol><hr><h2 id="_2-dars-iot-arxitekturasi-sensorlar-aktuatorlar-va-apparat-ta-minoti" tabindex="-1">2-dars: IoT arxitekturasi: Sensorlar, aktuatorlar va apparat ta&#39;minoti <a class="header-anchor" href="#_2-dars-iot-arxitekturasi-sensorlar-aktuatorlar-va-apparat-ta-minoti" aria-label="Permalink to &quot;2-dars: IoT arxitekturasi: Sensorlar, aktuatorlar va apparat ta&#39;minoti&quot;">​</a></h2><ol><li>O&#39;zingiz o&#39;ylab topgan bitta IoT loyihasi (masalan, aqlli eshik qo&#39;ng&#39;irog&#39;i yoki aqlli akvarium) uchun zarur bo&#39;ladigan komponentlar ro&#39;yxatini tuzing: <ul><li>Kamida 2 ta sensor (analog va raqamli);</li><li>Kamida 2 ta aktuator (masalan, rele, motor, buzzer, ekran);</li><li>Bitta boshqaruvchi platasi (Arduino Uno yoki ESP32).</li></ul></li><li>Nima sababdan ushbu boshqaruvchi platasini tanlaganingizni asoslab bering (Wi-Fi kerakmi yoki oddiy hisoblash yetarlimi?).</li><li>Nima uchun 220V tokda ishlaydigan elektr asboblarini to&#39;g&#39;ridan-to&#39;g&#39;ri mikrokontroller piniga ulab bo&#39;lmasligini va bu yerda rele moduli qanday vazifani bajarishini tushuntiring.</li></ol><hr><h2 id="_3-dars-iot-arxitekturasi-tarmoq-bulut-va-foydalanuvchi-interfeysi" tabindex="-1">3-dars: IoT arxitekturasi: Tarmoq, bulut va foydalanuvchi interfeysi <a class="header-anchor" href="#_3-dars-iot-arxitekturasi-tarmoq-bulut-va-foydalanuvchi-interfeysi" aria-label="Permalink to &quot;3-dars: IoT arxitekturasi: Tarmoq, bulut va foydalanuvchi interfeysi&quot;">​</a></h2><ol><li>O&#39;z loyihangiz uchun eng ma&#39;qul simsiz aloqa texnologiyasini tanlang (Wi-Fi, Bluetooth Low Energy, LoRaWAN yoki Zigbee) va nima sababdan aynan shu texnologiya tanlanganini (masofa, quvvat sarfi, tezlik) tushuntiring.</li><li>Mikrokontrollerdan bulutga ma&#39;lumot uzatishda nima uchun HTTP emas, balki MQTT protokoli tavsiya etilishini 3 ta asosiy sabab bilan bayon qiling.</li><li>Foydalanuvchi mobil telefondagi Blynk (yoki shunga o&#39;xshash) dashboard orqali qanday ko&#39;rsatkichlarni ko&#39;rishi va qanday tugmalar orqali qurilmani boshqarishi mumkinligining sxematik eskizini chizing yoki matn ko&#39;rinishida tavsiflang.</li><li>Tizimda qaysi muhim qarorlar internetga qaramasdan Edge (lokal) darajasida, qaysilari esa Cloud (bulut) darajasida qabul qilinishini ajratib bering.</li></ol><hr><h2 id="mentor-uchun" tabindex="-1">Mentor uchun <a class="header-anchor" href="#mentor-uchun" aria-label="Permalink to &quot;Mentor uchun&quot;">​</a></h2><h3 id="baholash-mezonlari-jami-100-ball" tabindex="-1">Baholash mezonlari (Jami 100 ball) <a class="header-anchor" href="#baholash-mezonlari-jami-100-ball" aria-label="Permalink to &quot;Baholash mezonlari (Jami 100 ball)&quot;">​</a></h3><ul><li><strong>1-dars vazifasi (30 ball):</strong> IoT ning M2M tabiati to&#39;g&#39;ri tushunilgani, real hayotiy muammolar aniqlangani va to&#39;g&#39;ri sohalarga ajratilgani.</li><li><strong>2-dars vazifasi (35 ball):</strong> Sensor va aktuatorlar to&#39;g&#39;ri tanlangani, analog/raqamli farqi, relening galvanik izolyatsiya roli hamda Arduino/ESP32 imkoniyatlari to&#39;g&#39;ri baholangani.</li><li><strong>3-dars vazifasi (35 ball):</strong> Simsiz tarmoq turi (Wi-Fi vs LoRaWAN), MQTT protokoli afzalligi, dashboard loyihasi hamda Edge vs Cloud Computing tushunchalari to&#39;g&#39;ri qo&#39;llangani.</li></ul><h3 id="eslatma" tabindex="-1">Eslatma <a class="header-anchor" href="#eslatma" aria-label="Permalink to &quot;Eslatma&quot;">​</a></h3><ul><li>O&#39;quvchilar apparat qismlarini (hardware) shunchaki nomma-nom sanab ketmasdan, ularning signallari (kirish sensori -&gt; mikrokontroller dasturi -&gt; chiqish aktuatori) qanday zanjir hosil qilishini tushunganiga e&#39;tibor bering.</li></ul>',16))]),i("div",b,[i("h2",g,[r(t,{name:"list-checks"}),a[3]||(a[3]=l(" Baholash mezoni ",-1)),a[4]||(a[4]=i("a",{class:"header-anchor",href:"#baholash-mezoni","aria-label":'Permalink to "<Icon name="list-checks" /> Baholash mezoni"'},"​",-1))]),a[5]||(a[5]=o('<p><strong>Mavzular:</strong></p><ol><li>IoT tushunchasi va qo‘llanish sohalari: Kevin Eshton, M2M, Smart Home, IIoT, IoMT, Smart Agriculture, Smart City</li><li>IoT arxitekturasi: Sensorlar, aktuatorlar va apparat ta&#39;minoti: analog vs raqamli sensorlar, rele, servomotor, Arduino vs ESP32</li><li>IoT arxitekturasi: Tarmoq, bulut va foydalanuvchi interfeysi: Wi-Fi, BLE, LoRaWAN, MQTT vs HTTP, Edge vs Cloud, Blynk dashboard</li></ol><hr><h2 id="baholash-mezonlari" tabindex="-1">Baholash mezonlari <a class="header-anchor" href="#baholash-mezonlari" aria-label="Permalink to &quot;Baholash mezonlari&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mezon</th><th>Tavsif</th><th>Maks. ball</th></tr></thead><tbody><tr><td><strong>IoT Tushunchasi va M2M</strong></td><td>Kevin Eshton, M2M mexanizmi, an&#39;anaviy internetdan farqi, 5 ta qo&#39;llanish sohasi (Smart Home, IIoT, IoMT, Aqlli qishloq xo&#39;jaligi, Smart City)</td><td>30 ball</td></tr><tr><td><strong>Sensorlar, Aktuatorlar &amp; Apparat</strong></td><td>Analog vs raqamli sensorlar, rele va uning xavfsizlik vazifasi, servomotor, Arduino Uno vs ESP32 imkoniyatlari</td><td>35 ball</td></tr><tr><td><strong>Tarmoq, MQTT va Bulut</strong></td><td>Simsiz tarmoqlar (Wi-Fi, BLE, LoRaWAN), MQTT (Publish/Subscribe/Broker), Edge vs Cloud computing, Blynk interfeysi</td><td>35 ball</td></tr><tr><td><strong>JAMI</strong></td><td></td><td><strong>100 ball</strong></td></tr></tbody></table><hr><h2 id="o-quvchilar-natijalari-jadvali" tabindex="-1">O&#39;quvchilar natijalari jadvali <a class="header-anchor" href="#o-quvchilar-natijalari-jadvali" aria-label="Permalink to &quot;O&#39;quvchilar natijalari jadvali&quot;">​</a></h2><table tabindex="0"><thead><tr><th>№</th><th>O&#39;quvchi F.I.Sh.</th><th>IoT Asoslari &amp; M2M (30)</th><th>Apparat &amp; Sensorlar (35)</th><th>Tarmoq &amp; Bulut (35)</th><th>Jami ball (100)</th><th>Izoh</th></tr></thead><tbody><tr><td>1</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>2</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>3</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>4</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>5</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>6</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>7</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>8</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>9</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>10</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>11</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>12</td><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><hr><h2 id="mentor-qaydlari-va-tahlil" tabindex="-1">Mentor qaydlari va tahlil <a class="header-anchor" href="#mentor-qaydlari-va-tahlil" aria-label="Permalink to &quot;Mentor qaydlari va tahlil&quot;">​</a></h2><ul><li><strong>Darsdagi asosiy qiyinchiliklar:</strong> O&#39;quvchilar ko&#39;pincha IoT ni oddiy masofadan pult bilan boshqariladigan texnika deb tushunishadi. Qurilmalar inson aralashuvisiz (M2M) mustaqil ma&#39;lumot almashishi va qaror qabul qilishi asosiy shart ekanini ta&#39;kidlash lozim. Shuningdek, 5V mikrokontroller bilan 220V yuqori kuchlanishni bevosita ulab bo&#39;lmasligi, rele orqali galvanik izolyatsiya zarurligi kabi xavfsizlik tushunchalarini sinchkovlik bilan tushuntirish muhim.</li><li><strong>Iqtidorli o&#39;quvchilar uchun:</strong> Real ESP32 moduli yoki Tinkercad simulyatorida harorat va namlik sensori asosida shaxsiy Telegram botga yoki Blynk mobil ilovasiga bildirishnoma yuboruvchi mustaqil arxitektura chizmasini tuzish topshirig&#39;i berilishi mumkin.</li></ul>',11))])])}const p=n(h,[["render",k]]);export{z as __pageData,p as default};
